const W=160,H=120,N=W*H;
const $=id=>document.getElementById(id);
const sections=[['play','Model playground'],['data','Depth Anything V2'],['detail','Depth Pro'],['geometry','MoGe-2 in 3D']];
const state={section:'play',sample:0,revealed:false,stage:0,context:22,x:80,y:60,yaw:-25,pitch:12,source:'moge',pro:false};
const imgPath=i=>`assets/nyu${i}-rgb.png`;
const loadImage=src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src});
const read=async path=>{const r=await fetch(path);if(!r.ok)return null;const b=await r.arrayBuffer();return new Float32Array(b)};
const [photos,refs,da,moge,pro,points]=await Promise.all([
 Promise.all([0,1,2].map(i=>loadImage(imgPath(i)))),
 Promise.all([0,1,2].map(i=>read(`assets/nyu${i}-reference.f32`))),
 Promise.all([0,1,2].map(i=>read(`assets/nyu${i}-da2.f32`))),
 Promise.all([0,1,2].map(i=>read(`assets/nyu${i}-moge.f32`))),
 Promise.resolve([null,null,null]), // Depth Pro is available through the linked external demo.
 Promise.all([0,1,2].map(i=>read(`assets/nyu${i}-moge-xyz.f32`)))
]);
const colour=t=>{t=Math.max(0,Math.min(1,t));return [Math.round(22+204*t),Math.round(61+167*t),Math.round(91+145*t),255]};
function bounds(a){let v=Array.from(a).filter(Number.isFinite).sort((a,b)=>a-b);return [v[Math.floor(v.length*.01)],v[Math.floor(v.length*.99)]]}
const daBounds=da.map(bounds);
function rgbData(i){let c=document.createElement('canvas');c.width=W;c.height=H;let cx=c.getContext('2d');cx.drawImage(photos[i],0,0,W,H);return cx.getImageData(0,0,W,H)}
const rgb=[0,1,2].map(rgbData);
function field(kind,i){let d=new ImageData(W,H);let values=kind==='da'?da[i]:kind==='moge'?moge[i]:kind==='pro'?pro[i]:refs[i];if(!values)return null;for(let j=0;j<N;j++){let v=values[j],t;if(kind==='da'){let [lo,hi]=daBounds[i];t=1-(v-lo)/(hi-lo)}else t=(v-1)/5;d.data.set(!Number.isFinite(v)||v<=0?[191,202,208,255]:colour(t),j*4)}return d}
const maps={};['da','moge','pro','ref'].forEach(k=>maps[k]=[0,1,2].map(i=>field(k,i)));
function image(id,data){let c=$(id);if(!c||!data)return; c.getContext('2d').putImageData(data,0,0)}
function canvas(id,label){return `<canvas id="${id}" class="image-canvas" width="160" height="120" role="img" aria-label="${label}"></canvas>`}
function fig(id,label,caption){return `<figure><strong>${label}</strong>${canvas(id,label)}<figcaption>${caption}</figcaption></figure>`}
function sample(){return `<label class="shared-sample">Working image <select id="sample"><option value="0">A - indoor scene</option><option value="1">B - indoor scene</option><option value="2">C - indoor scene</option></select></label>`}
function bindSample(draw){$('sample').value=state.sample;$('sample').onchange=e=>{state.sample=+e.target.value;draw()}}
function head(k,title,intro){return `<div class="section-head simple-head"><div><p class="eyebrow">${k}</p><h2>${title}</h2><p>${intro}</p></div></div>`}
function q(items){$('questions').innerHTML=`<h2>Questions to discuss</h2><div class="qgrid">${items.map(([title,question,answer])=>`<article class="qcard"><h3>${title}</h3><p>${question}</p><details><summary>Discuss the answer</summary><p>${answer}</p></details></article>`).join('')}</div>`}
function range(id,label,value,min,max,unit=''){return `<label><span>${label} <output id="${id}-out">${value}${unit}</output></span><input id="${id}" type="range" min="${min}" max="${max}" value="${value}"></label>`}
function bind(id,fn,unit=''){let el=$(id);el.oninput=()=>{if($(id+'-out'))$(id+'-out').textContent=el.value+unit;fn(+el.value)}}
function navigate(){ $('nav').innerHTML=sections.map(([id,name],i)=>`<button type="button" data-nav="${id}" aria-current="${state.section===id?'step':'false'}"><small>0${i+1}</small>${name}</button>`).join('');document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.section=b.dataset.nav;history.replaceState(null,'','#'+state.section);render();$('lab').focus({preventScroll:true})})}
const provenance=`<details class="sources"><summary>About these examples and predictions</summary><p>These three images and processed sensor depth maps come from <a href="https://cs.nyu.edu/~fergus/datasets/nyu_depth_v2.html" target="_blank" rel="noreferrer">NYU Depth V2</a>. Predictions are precomputed on the same RGB images: Depth Anything V2 Small (relative inverse-depth scores), MoGe-2 Small (metric depth), and, where available, Depth Pro (metric depth). They are predictions, not ground truth; the sensor reference is also imperfect. These examples are not a benchmark and may overlap training data.</p><p>Colour is a visualisation: relative scores are normalised independently for each image; metric maps share a 1-6 m display range and values outside it are clipped. Equal colours across relative and metric maps do not mean equal distances.</p></details>`;
function play(){ $('lab').innerHTML=`<div class="workspace">${head('Model playground','What can current models infer from one image?','A single image can be explained by many different 3D scenes. Depth models use patterns learned from training data to predict a plausible depth map.')}<div class="info"><strong>Before revealing the predictions:</strong> Choose an image and look for a boundary, narrow object or reflective surface. Where might depth be difficult to predict? Where do you expect the models to agree?</div>${sample()}<div class="case-switch"><button id="reveal" type="button">${state.revealed?'Hide predictions':'Reveal predictions'}</button></div><div class="play-images"><figure><strong>Input photograph</strong>${canvas('rgb','RGB input')}<figcaption>NYU Depth V2 camera image.</figcaption></figure><div id="prediction-area"></div></div><div class="legend-line"><span class="gradient"></span> Dark = near &nbsp; Light = far <span>Metric displays use 1-6 m; the relative map is normalised separately.</span></div><div class="note">The predictions shown here were computed in advance. To try your own image, use the authors' demos: <a href="https://huggingface.co/spaces/depth-anything/Depth-Anything-V2" target="_blank" rel="noreferrer">Depth Anything V2</a> and <a href="https://huggingface.co/spaces/Ruicheng/MoGe-2" target="_blank" rel="noreferrer">MoGe-2</a>. The demos may have a queue. For Depth Pro, you can also try <a href="https://huggingface.co/spaces/lightly-ai/ml-depth-pro" target="_blank" rel="noreferrer">this independent demo</a>.</div><p>Use the same photograph when comparing models. Different checkpoints, preprocessing and colour scales can affect an apparent difference. None of these views shows what is hidden behind the visible surface.</p>${provenance}</div>`;
function draw(){image('rgb',rgb[state.sample]);$('reveal').textContent=state.revealed?'Hide predictions':'Reveal predictions';let area=$('prediction-area');if(!state.revealed){area.innerHTML='<div class="conceal"><strong>What do you expect to see?</strong><p>Reveal the depth maps to compare the model predictions with the sensor reference.</p></div>';return}let includePro=!!pro[state.sample];area.innerHTML=`<div class="prediction-grid">${fig('pd','Depth Anything V2','Relative inverse depth; larger scores indicate nearer points.')}${fig('pm','MoGe-2','Metric depth prediction, displayed in metres.')}${includePro?fig('pp','Depth Pro','Metric depth prediction, displayed in metres.'):''}${fig('pr','Sensor reference','Processed RGB-D depth; an imperfect reference.')}</div>${includePro?'':'<p class="hint">For these NYU images, Depth Pro is available through the linked demo. You can compare its published outputs on two other images below.</p>'}`;image('pd',maps.da[state.sample]);image('pm',maps.moge[state.sample]);image('pp',maps.pro[state.sample]);image('pr',maps.ref[state.sample])}bindSample(draw);$('reveal').onclick=()=>{state.revealed=!state.revealed;draw()};draw();q([['Ambiguity and priors','If a model gives a precise-looking distance, has it resolved the ambiguity of a single image?','No. It predicts a plausible answer using learned regularities. The same projection can still arise from different scenes, and a confident-looking map can be wrong.'],['Compare predictions','Two maps disagree at a shiny surface. What further evidence would help determine which is correct?','A reliable depth measurement or additional calibrated views could help. Sensor references can also be unreliable on reflective surfaces, so the measurement process matters.']])}
const stages=[{title:'1. Labelled synthetic scenes',body:'Rendered scenes provide image-depth pairs, including fine geometric detail. Their appearance and scene distribution may differ from real photographs.',tag:'SYNTHETIC IMAGE + DEPTH',show:'synth'}, {title:'2. Train a large teacher',body:'A large teacher is trained with labelled synthetic examples. Its parameters are learned before it produces labels for real images.',tag:'TRAINING STAGE',show:'train'}, {title:'3. Label real images',body:'The fixed teacher predicts pseudo-depth for large numbers of unlabelled real images. The pseudo-labels can contain teacher errors.',tag:'REAL IMAGE + TEACHER PREDICTION',show:'real'}, {title:'4. Train student models',body:'Students learn from the pseudo-labelled real images. The training set now contains real image appearances, but its depth targets are still generated by the teacher.',tag:'STUDENT TRAINING',show:'student'}];
function data(){ $('lab').innerHTML=`<div class="workspace">${head('Depth Anything V2','How can a depth model learn from unlabelled photos?','Follow the paper from accurate synthetic labels to diverse real images. This is the training pipeline, not the sequence run each time a student makes a prediction.')}<div class="info"><strong>Question:</strong> Synthetic data supplies depth but has a domain gap. Unlabelled real photographs have realistic appearance but no depth labels. How does the paper bring the two together?</div>${sample()}<div class="flow-buttons">${stages.map((s,i)=>`<button type="button" data-stage="${i}" aria-pressed="${state.stage===i}">${s.title}</button>`).join('')}</div><div class="stage-layout"><div class="stage-visual" id="stage-visual"></div><div class="stage-explain"><p class="eyebrow" id="stage-tag"></p><h3 id="stage-title"></h3><p id="stage-body"></p><div class="note" id="stage-note"></div></div></div><p class="hint">The diagram describes the paper's training procedure. The displayed Depth Anything V2 Small prediction is an actual final student-model output on the selected photo, used here as an example; it is not a recorded output of the paper's large teacher.</p><p><a href="https://proceedings.neurips.cc/paper_files/paper/2024/hash/26cfdcd8fe6fd75cc53e92963a656c58-Abstract-Conference.html" target="_blank" rel="noreferrer">Read the Depth Anything V2 paper</a></p></div>`;
function draw(){let s=stages[state.stage];document.querySelectorAll('[data-stage]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===state.stage)));$('stage-tag').textContent=s.tag;$('stage-title').textContent=s.title;$('stage-body').textContent=s.body;$('stage-note').textContent=['The depth of the rendered scene is available from its geometry, but labels are useful only if the training examples cover the situations we care about.','The teacher learns from synthetic scenes. It can make errors on real images it has not seen before.','The final model output shown here stands in for the kind of dense target a teacher produces; the exact teacher output is not available in this tutorial.','The student learns to predict dense depth on real-looking images. The pseudo-labels do not constitute independent ground truth.'][state.stage];let vis=$('stage-visual');if(state.stage<2){vis.innerHTML=`<div class="synthetic-pair"><div><strong>Rendered scene</strong><svg viewBox="0 0 240 160" role="img" aria-label="Illustration of a rendered room with a table and a sphere"><rect width="240" height="160" fill="#cfe6eb"/><path d="M0 112 L240 112 L240 160 L0 160Z" fill="#b3c5ae"/><rect x="120" y="62" width="90" height="56" fill="#db945a"/><path d="M115 60 L162 37 L218 61 L168 84Z" fill="#efb577"/><circle cx="73" cy="102" r="30" fill="#3787a5"/><path d="M0 0 L45 32 L45 112 L0 112Z" fill="#9fc4d1"/></svg></div><div><strong>Rendered depth</strong><svg viewBox="0 0 240 160" role="img" aria-label="Illustration of the rendered scene's depth"><rect width="240" height="160" fill="#d1dfe9"/><path d="M0 112 L240 112 L240 160 L0 160Z" fill="#7d9bae"/><rect x="120" y="62" width="90" height="56" fill="#65889e"/><path d="M115 60 L162 37 L218 61 L168 84Z" fill="#89a7b8"/><circle cx="73" cy="102" r="30" fill="#245b78"/><path d="M0 0 L45 32 L45 112 L0 112Z" fill="#b0c7d4"/></svg></div></div><p class="hint">Illustrative rendered scene and its schematic depth, not a sample from the training data.</p>`}else{vis.innerHTML=`<div class="image-cards">${fig('data-rgb','Real photograph','Selected working image.')}${fig('data-pred','Example depth prediction','Actual final Depth Anything V2 Small output.')}</div>`;image('data-rgb',rgb[state.sample]);image('data-pred',maps.da[state.sample])}}
bindSample(draw);document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{state.stage=+b.dataset.stage;draw()});draw();q([['Why pseudo-label?','Why train on pseudo-labelled real images after training on synthetic examples?','Real images provide broader, more realistic appearances. Teacher labels add depth supervision, trading some label accuracy for diverse real image coverage.'],['Limits of the labels','Could a student surpass its teacher on some images, or must it reproduce every error?','It can differ and sometimes improve because of the data distribution, architecture, augmentation and optimisation. The pseudo-labels can also propagate systematic teacher errors.']])}
function detail(){ $('lab').innerHTML=`<div class="workspace">${head('Depth Pro','Why look at the image at more than one scale?','A small image region preserves detail but can lose scene context. A full image provides context but may compress fine boundaries.')}<div class="info"><strong>Question:</strong> What can be recognised from a local crop, and what can the rest of the scene tell you about its depth?</div>${sample()}<div class="lab"><aside class="controls"><h3>Explore context</h3>${range('context','Neighbourhood radius',state.context,6,55,' px')}<p class="hint">Click the photograph to move the crop. The slider changes this illustration; it does not run or modify Depth Pro.</p></aside><div class="viz"><div class="image-cards detail-cards">${fig('detail-rgb','Full photograph','Orange box shows the selected neighbourhood.')}${fig('detail-crop','Local crop','Enlarged image content, not a model feature.')}${pro[state.sample]?fig('detail-pro','Depth Pro prediction','Actual precomputed metric prediction.'):''}</div><div class="note">The crop makes an information trade-off visible. It is not an ablation and does not prove which feature caused a prediction. ${pro[state.sample]?'Depth Pro output is shown for the same image.':'Try the actual model through the independent demo below.'}</div></div></div><div class="model-block"><h3>Depth Pro combines scales</h3><div class="scale-path"><div><strong>Whole image</strong><p>Scene layout and global context</p></div><div><strong>Overlapping image patches</strong><p>Local high-resolution information</p></div><div><strong>Dense prediction</strong><p>Features are fused to predict metric depth</p></div></div><p>Depth Pro uses a multiscale vision transformer, training data and a focal-length estimator. The crop above illustrates why scales matter; it is not an implementation of the network. The prediction also depends on its training and other design choices.</p><p><a href="https://machinelearning.apple.com/research/depth-pro" target="_blank" rel="noreferrer">Depth Pro paper and project</a> · <a href="https://huggingface.co/spaces/lightly-ai/ml-depth-pro" target="_blank" rel="noreferrer">Independent interactive demo</a></p></div></div>`;
function draw(){image('detail-rgb',rgb[state.sample]);let ctx=$('detail-rgb').getContext('2d');ctx.strokeStyle='#e87522';ctx.lineWidth=2;ctx.strokeRect(state.x-state.context,state.y-state.context,state.context*2,state.context*2);let cc=$('detail-crop').getContext('2d');cc.fillStyle='#e7eff4';cc.fillRect(0,0,W,H);let s=state.context;cc.drawImage(photos[state.sample],(state.x-s)*4,(state.y-s)*4,s*8,s*8,0,0,W,H);image('detail-pro',maps.pro[state.sample])}bindSample(draw);bind('context',v=>{state.context=v;draw()},' px');$('detail-rgb').onclick=e=>{let r=e.currentTarget.getBoundingClientRect();state.x=Math.min(W-1,Math.max(0,Math.floor((e.clientX-r.left)/r.width*W)));state.y=Math.min(H-1,Math.max(0,Math.floor((e.clientY-r.top)/r.height*H)));draw()};draw();q([['Local versus global','Why might an image crop containing only a small patch of wall be ambiguous?','Similar textures can occur at many depths and scales. The surrounding scene may supply object and layout cues, though these remain learned priors rather than a geometric guarantee.'],['Assessing an architectural claim','A sharp depth boundary appears in the prediction. Does that establish that multiscale fusion caused it?','No. Training data, resolution, losses and many other factors matter. A controlled ablation or the paper’s experiments are needed to isolate the effect.']])}
function geometry(){ $('lab').innerHTML=`<div class="workspace">${head('MoGe-2 in 3D','What geometry does the model predict?','A depth map gives a value at each image location. MoGe-2 predicts a 3D point map, placing visible image points in camera-centred 3D space.')}<div class="info"><strong>Question:</strong> What changes when you leave the original camera view? Rotate the geometry and compare it with the input photograph. Which surfaces and gaps can you actually see?</div>${sample()}<div class="lab"><aside class="controls"><h3>Explore the geometry</h3><label>Point source<select id="cloud-source"><option value="moge">MoGe-2 predicted point map</option><option value="reference">Sensor depth back-projected</option></select></label>${range('yaw','Rotate',state.yaw,-100,100,'°')}${range('pitch','Tilt',state.pitch,-55,55,'°')}<button class="secondary" id="reset-view">Reset view</button><p class="hint">Drag the 3D view or use the sliders. Click a location in the input photograph to trace its point. Only the visible surface is represented.</p></aside><div class="viz"><div class="panel"><div class="visual-title"><h3>Camera and visible 3D points</h3><small>DRAG TO ROTATE</small></div><div class="cloud-linked"><figure><strong>Input photograph</strong>${canvas('cloud-image','Input image. Select a pixel to highlight its 3D point.')}<figcaption>Click to select a point.</figcaption></figure><canvas id="cloud" class="cloud-canvas" width="760" height="450" role="img" aria-label="Rotatable RGB coloured 3D point map and input camera"></canvas></div><p id="cloud-status" class="hint"></p></div></div></div><div class="model-block"><h3>Why a point map?</h3><div class="scale-path"><div><strong>Image</strong><p>One RGB value per pixel.</p></div><div><strong>Depth map</strong><p>One depth per pixel. A camera model is needed to obtain 3D coordinates.</p></div><div><strong>Point map</strong><p>A 3D coordinate for each visible image location.</p></div></div><p>MoGe-2 predicts a metric-scale point map. Its training also addresses noisy geometry and sharp detail. The reference view here back-projects sensor depth with fixed NYU camera intrinsics; it is useful for comparison but is not the model's point map.</p><div class="note">Neither output proves the shape behind an occluder. A point can be incorrect even when its colour makes the rendering look convincing. The relative outputs, metric estimates and camera assumptions answer different questions.</div><p><a href="https://wangrc.site/MoGe2Page/" target="_blank" rel="noreferrer">MoGe-2 paper and project</a> · <a href="https://huggingface.co/spaces/Ruicheng/MoGe-2" target="_blank" rel="noreferrer">Try the authors' demo</a></p></div>${provenance}</div>`;
let c=$('cloud'),ctx=c.getContext('2d');
function coord(x,y){let i=y*W+x;if(state.source==='moge'){let p=points[state.sample];if(!p)return null;let X=p[3*i],Y=p[3*i+1],Z=p[3*i+2];return Number.isFinite(X)&&Number.isFinite(Y)&&Number.isFinite(Z)&&Z>0&&Z<10?[X,Y,Z]:null}let z=refs[state.sample][i];if(!Number.isFinite(z)||z<=0||z>10)return null;return [((x+.5)*4-325.5824)*z/518.8579,((y+.5)*4-253.7362)*z/519.4696,z]}
function project(v){let a=state.yaw*Math.PI/180,b=state.pitch*Math.PI/180,X=v[0],Y=v[1],Z=v[2]-2.8,x=X*Math.cos(a)+Z*Math.sin(a),z=-X*Math.sin(a)+Z*Math.cos(a),y=Y*Math.cos(b)-z*Math.sin(b),scale=80;return [380+x*scale,215+y*scale,z]}
function draw(){image('cloud-image',rgb[state.sample]);let ci=$('cloud-image').getContext('2d');ci.strokeStyle='#ec7f24';ci.lineWidth=2;ci.beginPath();ci.arc(state.x,state.y,4,0,2*Math.PI);ci.stroke();ctx.fillStyle='#edf5f9';ctx.fillRect(0,0,760,450);let arr=[];for(let y=2;y<H;y+=2)for(let x=2;x<W;x+=2){let p=coord(x,y);if(!p)continue;let r=project(p),i=(y*W+x)*4;arr.push({r,col:`rgb(${rgb[state.sample].data[i]},${rgb[state.sample].data[i+1]},${rgb[state.sample].data[i+2]})`})}arr.sort((a,b)=>b.r[2]-a.r[2]);for(const p of arr){ctx.fillStyle=p.col;ctx.fillRect(p.r[0]-2,p.r[1]-2,4,4)}let [cx,cy]=project([0,0,0]),p=coord(state.x,state.y);if(p){let [x,y]=project(p);ctx.strokeStyle='#e67621';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(x,y);ctx.stroke();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(x,y,7,0,Math.PI*2);ctx.fill();ctx.stroke();}$('cloud-status').textContent=`${arr.length} sampled visible points. Orange marks the input camera and selected ray. ${state.source==='moge'?'Points are the model’s predicted metric point map.':'Points are sensor depths back-projected with fixed NYU intrinsics.'} ${p?`Selected point (X, Y, Z): ${p.map(v=>v.toFixed(2)).join(', ')} m.`:'No valid point at this location.'}`;ctx.fillStyle='#d76c1f';ctx.beginPath();ctx.arc(cx,cy,7,0,2*Math.PI);ctx.fill();ctx.fillStyle='#153f59';ctx.font='bold 15px Arial';ctx.fillText('INPUT CAMERA',cx+10,cy-8);$('yaw-out').textContent=state.yaw+'°';$('pitch-out').textContent=state.pitch+'°'}
bindSample(draw);$('cloud-source').value=state.source;$('cloud-source').onchange=e=>{state.source=e.target.value;draw()};bind('yaw',v=>{state.yaw=v;draw()},'°');bind('pitch',v=>{state.pitch=v;draw()},'°');$('reset-view').onclick=()=>{state.yaw=-25;state.pitch=12;$('yaw').value=state.yaw;$('pitch').value=state.pitch;draw()};$('cloud-image').onclick=e=>{let r=e.currentTarget.getBoundingClientRect();state.x=Math.max(0,Math.min(W-1,Math.floor((e.clientX-r.left)/r.width*W)));state.y=Math.max(0,Math.min(H-1,Math.floor((e.clientY-r.top)/r.height*H)));draw()};let drag=null;c.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,yaw:state.yaw,pitch:state.pitch};c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!drag)return;state.yaw=Math.max(-100,Math.min(100,drag.yaw+(e.clientX-drag.x)*.5));state.pitch=Math.max(-55,Math.min(55,drag.pitch+(e.clientY-drag.y)*.5));$('yaw').value=state.yaw;$('pitch').value=state.pitch;draw()};c.onpointerup=()=>drag=null;c.onpointercancel=()=>drag=null;draw();q([['Depth or point map?','What extra information is needed to turn a depth map into a 3D point map?','A depth convention and a camera model, including intrinsics, define the viewing ray for each pixel. Each depth can then be back-projected along the appropriate ray.'],['Visible is not complete','Does a good-looking point cloud establish the geometry behind a sofa or wall?','No. It represents a prediction for the visible image locations. Hidden surfaces are not observed, and apparent quality does not guarantee metric accuracy.']])}
// Paper figures are supplied by the Depth Pro paper and are not locally generated predictions.
const paperCases=[{key:'dis',name:'Bird cages',task:'Trace the thin cage bars. Which model keeps them distinct from the background?'},{key:'am',name:'Cat',task:'Inspect the fine fur at the silhouette. Where does depth meet the background?'}];
let paperCase=0;
function paperCompare(){return `<div class="panel paper-block"><div class="visual-title"><h3>Try more challenging images</h3><small>RESULTS FROM THE DEPTH PRO PAPER</small></div><p>Predict what will happen at the fine structures, then compare the paper's actual outputs. These images do not have a metric reference here.</p><div class="case-switch"><button type="button" data-paper="0">Bird cages</button><button type="button" data-paper="1">Cat</button></div><p id="paper-task" class="info"></p><div class="paper-grid"><figure><strong>Input photograph</strong><img id="paper-input" alt="Selected input photograph"></figure><figure><strong>Depth Pro</strong><img id="paper-pro" alt="Depth Pro prediction from the authors' paper"></figure><figure><strong>Depth Anything V2</strong><img id="paper-da" alt="Depth Anything V2 prediction from the Depth Pro paper"></figure></div><p class="hint">Figure 1 of <a href="https://arxiv.org/html/2410.02073#S1.F1" target="_blank" rel="noreferrer">Depth Pro</a>; photographs from DIS5K and AM-2K. Paper-provided visualisations have separate colour scales; colours do not give comparable metric distances. These examples are not a controlled ablation or a model ranking.</p></div>`}
function initPaperCompare(){function drawPaper(){let d=paperCases[paperCase];$('paper-task').textContent=d.task;for(let [id,s] of [['paper-input','input'],['paper-pro','pro'],['paper-da','da']])$(id).src=`assets/paper-${d.key}-${s}.jpg`;document.querySelectorAll('[data-paper]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.paper===paperCase)))}document.querySelectorAll('[data-paper]').forEach(b=>b.onclick=()=>{paperCase=+b.dataset.paper;drawPaper()});drawPaper()}
const basePlay=play;
play=function(){basePlay();$('lab').querySelector('.workspace').insertAdjacentHTML('beforeend',paperCompare());initPaperCompare()};

// The diagram represents the paper's training process; it is not live model training.
data=function(){const labels=['Synthetic pairs','Train teacher','Label real images','Train student'];const cards=[
 ['Precise geometry, limited coverage','A renderer provides synthetic RGB images and dense depth from the scene geometry. These labels can preserve thin structures, but the images do not cover every real-world appearance.','Gain: clean depth supervision','Remaining risk: synthetic-to-real shift'],
 ['A teacher learns from labelled scenes','The large DINOv2-G teacher is trained on synthetic image-depth pairs. Its parameters encode learned depth cues.','Gain: a predictor able to label photos','Remaining risk: mistakes on real images'],
 ['The fixed teacher labels real photos','The trained teacher produces pseudo-depth maps for many unlabelled real images. Each output becomes a training target, not a sensor measurement.','Gain: diverse real appearances with targets','Remaining risk: teacher errors in the targets'],
 ['The student learns from the labelled photos','A student model learns from real photos paired with the predicted depth maps from the teacher, called pseudo-labels. This transfers the teacher’s predictions without requiring measured depth for those photos.','Gain: a usable depth model','Remaining risk: systematic pseudo-label errors']];
$('lab').innerHTML=`<div class="workspace">${head('Depth Anything V2','How can synthetic depth help a model learn from real photos?','A size prior can favour one interpretation of an ambiguous image. A learned depth model also relies on prior knowledge, acquired from its training data.')}<div class="info"><strong>Question:</strong> Depth Anything V2 combines precise synthetic depth with diverse real photographs. Select each step to see how the training data and models change.</div><div class="teaching-pipeline" aria-label="Training pipeline">${labels.map((l,i)=>`<button type="button" data-stage="${i}" aria-pressed="${state.stage===i}"><span>${i+1}</span><strong>${l}</strong><small>${['Rendered RGB + depth','Learn weights','Teacher predicts','Real RGB + pseudo-depth'][i]}</small></button>`).join('')}</div><div class="pipeline-evidence"><div class="flow-detail"><p class="eyebrow" id="flow-kicker"></p><h3 id="flow-title"></h3><p id="flow-description"></p><div class="flow-gain" id="flow-gain"></div><div class="flow-risk" id="flow-risk"></div></div><div class="flow-picture" id="flow-picture"></div></div><p class="hint">The diagram illustrates the training process. The depth map shown in the final steps is a precomputed prediction from the trained Small model; the teacher's pseudo-label for this image is not shown.</p><div class="panel model-block"><h3>What evidence does the paper provide?</h3><p>The authors compared training sets for student models with the same ViT-S encoder. Select a training set to see how often the resulting model ordered annotated point pairs correctly on DA-2K, their relative-depth benchmark.</p><div class="case-switch"><button data-evidence="0">Synthetic labels only</button><button data-evidence="1">Synthetic + pseudo-labelled real</button><button data-evidence="2">Pseudo-labelled real only</button></div><div class="result-number"><strong id="da-score"></strong><span>DA-2K accuracy, higher is better</span></div><p id="da-evidence"></p><p class="hint">These values come from <a href="https://arxiv.org/html/2406.09414#S7.T5" target="_blank" rel="noreferrer">Depth Anything V2, Table 5</a>. This is one benchmark and one encoder; the paper also reports other datasets and discusses their limits. The other datasets and metrics in the paper help put this single comparison in context.</p></div></div>`;
function draw(){let d=cards[state.stage];document.querySelectorAll('[data-stage]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===state.stage)));$('flow-kicker').textContent='STEP '+(state.stage+1);$('flow-title').textContent=d[0];$('flow-description').textContent=d[1];$('flow-gain').textContent=d[2];$('flow-risk').textContent=d[3];let vis=$('flow-picture');if(state.stage<2){vis.innerHTML=`<svg viewBox="0 0 420 235" role="img" aria-label="Schematic synthetic room and its depth label"><rect width="420" height="235" fill="#e1eef3"/><path d="M0 155 L420 155 L420 235 L0 235Z" fill="#c1cdbf"/><rect x="240" y="88" width="100" height="76" fill="#bc8155"/><circle cx="135" cy="151" r="44" fill="#3788a5"/><rect x="20" y="18" width="147" height="30" rx="3" fill="#fff"/><text x="30" y="38" fill="#184b64" font-size="14">SYNTHETIC RGB</text><rect x="245" y="18" width="155" height="53" rx="3" fill="#fff"/><text x="254" y="39" fill="#184b64" font-size="13">${state.stage?'TRAIN TEACHER':'DEPTH FROM SCENE'}</text><text x="254" y="57" fill="#617d91" font-size="12">${state.stage?'learn parameters':'precise supervision'}</text></svg>`}else{vis.innerHTML=`<div class="image-cards">${fig('flow-rgb','Real photograph','No reference depth is supplied for pseudo-labelling.')}${fig('flow-output','Final student output','Actual Small checkpoint output; not the teacher target.')}</div>`;image('flow-rgb',rgb[0]);image('flow-output',maps.da[0])}}
let scores=[['89.8%','Only precise synthetic images supply training labels in this ablation.'],['94.1%','The student trains with both synthetic and pseudo-labelled real data.'],['95.3%','The student is trained on pseudo-labelled real data. The teacher that produced those labels was trained on labelled synthetic images.']];document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{state.stage=+b.dataset.stage;draw()});document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{let n=+b.dataset.evidence;document.querySelectorAll('[data-evidence]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('da-score').textContent=scores[n][0];$('da-evidence').textContent=scores[n][1]});draw();document.querySelector('[data-evidence="0"]').click();q([['Where do pseudo-labels come from?','The real photographs have no measured depth. Where do their training targets come from?','A teacher trained on labelled synthetic scenes predicts pseudo-depth for the real photographs. The photographs do not acquire independent sensor measurements.'],['Interpret the ablation','The ViT-S student improves on DA-2K using pseudo-labelled images. Does that guarantee every pseudo-label is accurate?','No. It is an aggregate benchmark result, not a correctness guarantee for each label, image or domain. Teacher errors can still be transferred.']])};
let proStage=0,proCase=0,proX=.63,proY=.52;
detail=function(){const desc=[['Input at several scales','The full image is resized to several scales, then split into patches. The larger field of view provides scene context.'],['Overlapping patches','At finer scales, overlapping patches preserve more local information and help avoid seams. The patch encoder shares weights across scales.'],['Encode and merge','A vision transformer encodes the patches. Patch features are merged into feature maps at multiple scales.'],['Fuse and predict','A decoder fuses the features and predicts canonical inverse depth. A supplied or estimated focal length converts it to metric depth.']];
$('lab').innerHTML=`<div class="workspace">${head('Depth Pro','How can one model combine context and fine detail?','Depth Pro combines information from the whole image with details from smaller patches to predict a high-resolution depth map.')}<div class="info"><strong>Question:</strong> How well do the predictions preserve fine structures? Click the photograph to inspect the same region in the image and both depth maps.</div><div class="case-switch"><button data-procase="0">Bird cages</button><button data-procase="1">Cat</button></div><div class="paper-grid pro-compare"><figure><strong>Input - click a detail</strong><canvas id="pro-input" width="600" height="400" role="img" aria-label="Photograph for selecting a detail"></canvas></figure><figure><strong>Depth Pro output</strong><canvas id="pro-output" width="600" height="400" role="img" aria-label="Actual Depth Pro output"></canvas></figure><figure><strong>Depth Anything V2 output</strong><canvas id="pro-alt" width="600" height="400" role="img" aria-label="Depth Anything V2 output from Depth Pro paper"></canvas></figure></div><div class="paper-grid crop-compare"><figure><strong>Input crop</strong><canvas id="pro-crop-rgb" width="360" height="240"></canvas></figure><figure><strong>Depth Pro crop</strong><canvas id="pro-crop-pro" width="360" height="240"></canvas></figure><figure><strong>Depth Anything V2 crop</strong><canvas id="pro-crop-da" width="360" height="240"></canvas></figure></div><p class="hint">Real input and predictions from <a href="https://arxiv.org/html/2410.02073#S1.F1" target="_blank" rel="noreferrer">Depth Pro, Figure 1</a>. Displays have independent colour scales. The comparison is qualitative, not an ablation of the architecture.</p><div class="panel model-block"><h3>Follow the multiscale path</h3><div class="flow-buttons">${['Image scales','Patch extraction','Shared encoder','Fuse & predict'].map((x,i)=>`<button data-prostage="${i}" aria-pressed="${i===proStage}">${i+1}. ${x}</button>`).join('')}</div><div class="pro-architecture"><div id="pro-diagram"></div><div><h3 id="pro-title"></h3><p id="pro-description"></p><p class="hint">Schematic of the method, not feature activations or a live inference.</p></div></div></div><div class="panel model-block"><h3>What changes when the training losses change?</h3><p>The authors tested which training losses help recover sharp boundaries. Choose a loss setting to see the reported boundary F1 on Hypersim. A higher F1 indicates better agreement with reference boundaries.</p><div class="case-switch"><button data-proablation="0">First- and second-order losses</button><button data-proablation="1">No derivative losses</button></div><div class="result-number"><strong id="pro-score"></strong><span>Hypersim boundary F1</span></div><p id="pro-interpret"></p><p class="hint">Reported values from <a href="https://arxiv.org/html/2410.02073#A2.T12" target="_blank" rel="noreferrer">Depth Pro, Table 12</a>, conditions 2A and 2D. This tests training losses, not the impact of patch fusion. The absolute difference is small and results vary across metrics.</p></div><p>For a photograph, Depth Pro estimates focal length if it is unavailable. Holding canonical inverse depth C and image width w fixed, the paper computes metric depth as D = f / (wC). An estimated focal length may be wrong; it does not remove the ambiguity of one image.</p><p><a href="https://machinelearning.apple.com/research/depth-pro" target="_blank" rel="noreferrer">Paper and project</a> · <a href="https://huggingface.co/spaces/lightly-ai/ml-depth-pro" target="_blank" rel="noreferrer">Independent demo for your own image</a></p></div>`;
let epoch=0,loaded=[];async function loadCase(){const ticket=++epoch;const d=paperCases[proCase];document.querySelectorAll('[data-procase]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===proCase)));let imgs=await Promise.all(['input','pro','da'].map(s=>loadImage(`assets/paper-${d.key}-${s}.jpg`)));if(ticket!==epoch)return;loaded=imgs;drawImages()}
function drawImages(){if(!loaded.length)return;for(let [i,id] of ['pro-input','pro-output','pro-alt'].entries()){let c=$(id),x=c.getContext('2d');x.drawImage(loaded[i],0,0,c.width,c.height);x.strokeStyle='#ff8e28';x.lineWidth=3;x.strokeRect((proX-.1)*c.width,(proY-.1)*c.height,.2*c.width,.2*c.height)}for(let [i,id] of ['pro-crop-rgb','pro-crop-pro','pro-crop-da'].entries()){let c=$(id),x=c.getContext('2d'),im=loaded[i],ww=im.width*.2,hh=im.height*.2;x.drawImage(im,(proX-.1)*im.width,(proY-.1)*im.height,ww,hh,0,0,c.width,c.height)}}
function drawStage(){let [title,text]=desc[proStage];$('pro-title').textContent=title;$('pro-description').textContent=text;document.querySelectorAll('[data-prostage]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===proStage)));let img=`assets/paper-${paperCases[proCase].key}-input.jpg`,depth=`assets/paper-${paperCases[proCase].key}-pro.jpg`;const picture=(cls,label,grid)=>`<figure class="pipe-picture"><div class="pipe-frame ${cls}"><img src="${img}" alt=""><span class="pipe-grid ${grid}"></span></div><figcaption>${label}</figcaption></figure>`;let inner='';if(proStage===0){inner=`<div class="pipe-scales">${picture('coarse','Coarse scale · 1 patch','grid-one')}${picture('middle','Middle scale · 9 patches','grid-three')}${picture('fine','Fine scale · 25 patches','grid-five')}</div><p class="hint">The grids indicate patch locations, not ViT tokens. The middle and fine patches overlap; exact crop boundaries are simplified here.</p>`}else if(proStage===1){inner=`<div class="pipe-scales">${picture('fine','Fine scale · patch locations','grid-five')}<figure class="pipe-picture"><div class="pipe-frame overlap"><img src="${img}" alt=""><i class="patch patch-a"></i><i class="patch patch-b"></i></div><figcaption>Two neighbouring patches overlap</figcaption></figure></div><p class="hint">The coloured outlines show an illustrative overlap. The actual model extracts 25 fine, 9 middle and 1 coarse patch.</p>`}else if(proStage===2){inner=`<div class="pipe-scales">${picture('fine','An input patch','grid-one')}<div class="pipe-operator">Shared<br>ViT encoder<span>→</span></div>${picture('feature','24 × 24 feature locations','grid-token')}</div><p class="hint">The grid shows the spatial size of each encoded patch. The image beneath is illustrative, not the encoder’s feature values.</p>`}else{inner=`<div class="pipe-scales">${picture('feature','Illustrated feature maps','grid-three')}<div class="pipe-operator">Merge +<br>decoder<span>→</span></div><figure class="pipe-picture"><div class="pipe-frame"><img src="${depth}" alt="Depth Pro prediction from the paper"></div><figcaption>Depth Pro output</figcaption></figure></div><p class="hint">Feature maps are illustrative. The depth map is the paper’s actual output for the selected image; the global image encoder is not depicted.</p>`}$('pro-diagram').innerHTML=inner}
document.querySelectorAll('[data-procase]').forEach(b=>b.onclick=()=>{proCase=+b.dataset.procase;loadCase();drawStage()});$('pro-input').onclick=e=>{let r=e.currentTarget.getBoundingClientRect();proX=Math.max(.1,Math.min(.9,(e.clientX-r.left)/r.width));proY=Math.max(.1,Math.min(.9,(e.clientY-r.top)/r.height));drawImages()};document.querySelectorAll('[data-prostage]').forEach(b=>b.onclick=()=>{proStage=+b.dataset.prostage;drawStage()});document.querySelectorAll('[data-proablation]').forEach(b=>b.onclick=()=>{let x=+b.dataset.proablation;document.querySelectorAll('[data-proablation]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));$('pro-score').textContent=x?'0.461':'0.465';$('pro-interpret').textContent=x?'Condition 2D removes the derivative-based losses.':'Condition 2A includes the first- and second-order derivative losses.'});loadCase();drawStage();document.querySelector('[data-proablation="0"]').click();q([['Context and detail','Why process both fine patches and a larger scene view?','Fine patches retain local information; a broad view provides context. Combining them is a design motivation, not a guarantee that a specific output pixel is correct.'],['Interpret the experiment','Does the loss ablation prove that multiscale patch encoding improves boundaries?','No. It compares training-loss settings while other choices are held within that experiment. Isolating the architecture requires an architectural ablation.']])};
const baseGeometry=geometry;
geometry=function(){baseGeometry();let block=document.createElement('div');block.className='model-block research-lab';block.innerHTML=`<h3>How does MoGe-2 recover scale?</h3><p>Scaling a scene about the camera leaves its projection unchanged, so the image alone cannot fix its size. MoGe-2 predicts relative geometry and global scale in separate branches. The scale branch uses the image encoder's global CLS token, and its prediction is combined with the geometry.</p><div class="lab"><aside class="controls"><h3>Illustrative scale</h3><label><span>Global scale <output id="scale-factor-out">1.0</output></span><input type="range" id="scale-factor" min="0.5" max="2" step="0.1" value="1"></label><p class="hint">Move the slider to scale the example point along its camera ray. The values illustrate scale ambiguity; they are not MoGe-2 predictions.</p></aside><div class="viz"><svg id="scale-figure" class="diagram" viewBox="0 0 700 250" role="img" aria-label="Illustration of relative geometry and scale"></svg><div class="formula" id="scale-math"></div><p class="hint">Scaling along the ray changes the point's distance but leaves its image position unchanged. MoGe-2's affine-invariant representation also involves a global shift, which this simplified diagram does not show.</p></div></div><div class="panel model-block"><h3>What can noisy depth labels do to boundaries?</h3><p>Depth measurements from LiDAR or structure from motion can be missing or misaligned around fine objects. MoGe-2's training pipeline filters suspect measurements and fills gaps using guidance from a model trained on synthetic data. Select each step to see a simplified depth profile.</p><div class="case-switch"><button data-refine="0">1. Noisy measurement</button><button data-refine="1">2. Filter mismatch</button><button data-refine="2">3. Complete missing area</button></div><svg id="refine-figure" class="diagram" viewBox="0 0 700 250" role="img" aria-label="Schematic depth profile at an object boundary"></svg><p id="refine-caption"></p><p class="hint">The orange dashed curve is the assumed true depth in this simplified example. The blue curve shows the selected measurement or completion. Real captured data does not generally provide the true profile.</p><h4>See how real annotations change</h4><p>In the ScanNet++ example from the MoGe-2 paper, the raw depth annotation misses parts of the cart. Select a stage to compare its depth map with the photograph. Black areas mark missing depth.</p><div class="case-switch annotation-switch"><button data-annotation="2">Raw annotation</button><button data-annotation="3">Filtered annotation</button><button data-annotation="4">Completed annotation</button></div><div class="annotation-grid"><figure><strong>RGB photograph</strong><svg viewBox="5 14 362 240" role="img" aria-label="ScanNet++ RGB photograph of a cart"><image href="assets/moge-paper-refinement.png" width="1860" height="603"/></svg></figure><figure><strong id="annotation-title">Raw annotation</strong><svg id="annotation-image" viewBox="747 14 362 240" role="img" aria-label="Selected depth annotation"><image href="assets/moge-paper-refinement.png" width="1860" height="603"/></svg></figure></div><p id="annotation-caption"></p><p class="hint">Images from <a href="https://arxiv.org/html/2507.02546v1#S3.F4" target="_blank" rel="noreferrer">MoGe-2, Figure 4</a>, using ScanNet++ data. The completed annotation is the authors’ processed training label, not independently measured ground truth. Colours represent the authors’ depth visualisation.</p><h4>Paper evidence: real-data refinement</h4><p>The paper also shows predictions from models trained with three different data configurations. The highlighted crop illustrates their differences.</p><figure class="ablation-figure"><img src="assets/moge-paper-ablation.png" alt="MoGe-2 paper comparison of the RGB image and geometry predicted by models trained with synthetic data, raw real data, and improved real data"><figcaption>From <a href="https://arxiv.org/html/2507.02546v1#S4.F7" target="_blank" rel="noreferrer">MoGe-2, Figure 7</a>. The boxed region is enlarged beside each image. These are model outputs, distinct from the training annotations above.</figcaption></figure><p>Compare the authors' ablations. Lower metric point error is better; higher boundary F1 is better.</p><div class="case-switch"><button data-mogedata="0">Synthetic data only</button><button data-mogedata="1">Raw real data</button><button data-mogedata="2">Improved real data</button></div><div class="readout"><div><span>Metric point error (%)</span><strong id="moge-error"></strong></div><div><span>Boundary F1</span><strong id="moge-f1"></strong></div><div><span>Interpretation</span><strong id="moge-label"></strong></div></div><p id="moge-desc"></p><p class="hint">Values from <a href="https://arxiv.org/html/2507.02546#S4.T4" target="_blank" rel="noreferrer">MoGe-2, Table 4</a>, ViT-Base. The metric point error is evaluated across seven datasets; boundary sharpness is evaluated on four. The raw and improved real-data configurations include the paper's real-data training setup; this is an aggregate evaluation, not evidence for an individual image.</p></div>`;
$('lab').querySelector('.workspace').append(block);
function scaleDraw(){let s=+$('scale-factor').value;$('scale-factor-out').textContent=s.toFixed(1);$('scale-math').textContent=`Illustrative relative point (0.5, 0.3, 2.0) × ${s.toFixed(1)} = (${(.5*s).toFixed(2)}, ${(.3*s).toFixed(2)}, ${(2*s).toFixed(2)}).`;let cx=90,cy=190, bx=cx+120*s,by=cy-68*s;$('scale-figure').innerHTML=`<line x1="25" y1="190" x2="660" y2="190" stroke="#c3d9e5"/><line x1="${cx}" y1="${cy}" x2="${bx}" y2="${by}" stroke="#d17a2c" stroke-width="3"/><circle cx="${cx}" cy="${cy}" r="7" fill="#164f6d"/><circle cx="${bx}" cy="${by}" r="8" fill="#da842f"/><text x="28" y="220" fill="#365b76" font-size="14">CAMERA</text><text x="${bx+12}" y="${by-8}" fill="#9c5a20" font-size="14">scaled point</text><text x="30" y="30" fill="#365b76" font-size="15">Same ray, different metric scale</text>`}
$('scale-factor').oninput=scaleDraw;scaleDraw();
let diagrams=[{line:'M 50 175 L 210 175 L 280 168 L 300 90 L 375 92 L 410 175 L 650 175',text:'The measured profile places part of the foreground object at the background depth.'},{line:'M 50 175 L 210 175 M 410 175 L 650 175',text:'Filtering removes measurements judged inconsistent near the boundary. A gap remains.'},{line:'M 50 175 L 250 175 L 250 90 L 390 90 L 390 175 L 650 175',text:'The completed profile fills the gap. In this illustration, it matches the assumed true depth.'}];function refineDraw(n){document.querySelectorAll('[data-refine]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===n)));$('refine-caption').textContent=diagrams[n].text;$('refine-figure').innerHTML=`<line x1="50" y1="210" x2="650" y2="210" stroke="#aac6d6"/><line x1="50" y1="55" x2="50" y2="210" stroke="#aac6d6"/><line x1="250" y1="50" x2="250" y2="195" stroke="#c8d8e0" stroke-dasharray="3 5"/><line x1="390" y1="50" x2="390" y2="195" stroke="#c8d8e0" stroke-dasharray="3 5"/><text x="260" y="32" font-size="14" fill="#365b76">THIN FOREGROUND OBJECT</text><path d="${diagrams[n].line}" fill="none" stroke="#238cb3" stroke-width="6" stroke-linecap="round"/><path d="M 50 175 L 250 175 L 250 90 L 390 90 L 390 175 L 650 175" fill="none" stroke="#df7727" stroke-width="3" stroke-dasharray="9 6"/><text x="55" y="235" font-size="13" fill="#365b76">position in image →</text><text x="57" y="70" font-size="13" fill="#365b76">near</text><text x="57" y="198" font-size="13" fill="#365b76">far</text><line x1="440" y1="70" x2="470" y2="70" stroke="#df7727" stroke-width="3" stroke-dasharray="7 5"/><text x="478" y="75" font-size="13" fill="#9e4f15">assumed true depth</text><line x1="440" y1="91" x2="470" y2="91" stroke="#238cb3" stroke-width="5"/><text x="478" y="96" font-size="13" fill="#18617e">selected profile</text>`}document.querySelectorAll('[data-refine]').forEach(b=>b.onclick=()=>refineDraw(+b.dataset.refine));refineDraw(0);
const annotationInfo={2:['Raw annotation','The original reconstruction contains missing areas and artifacts around the cart.'],3:['Filtered annotation','Suspect depths have been removed, leaving additional gaps to be completed.'],4:['Completed annotation','Completion fills gaps guided by synthetic-trained predictions while retaining real depth information.']};function annotationDraw(i){document.querySelectorAll('[data-annotation]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.annotation===i)));$('annotation-image').setAttribute('viewBox',`${5+i*371} 14 362 240`);$('annotation-title').textContent=annotationInfo[i][0];$('annotation-caption').textContent=annotationInfo[i][1]}document.querySelectorAll('[data-annotation]').forEach(b=>b.onclick=()=>annotationDraw(+b.dataset.annotation));annotationDraw(2);
let rows=[['12.4','13.3','Synthetic only','Sharper boundaries in this evaluation, with larger metric point error.'],['9.01','10.3','Raw real','Lower point error, with reduced boundary sharpness in this comparison.'],['9.20','12.5','Improved real','The refined labels recover some boundary sharpness while retaining similar point accuracy.']];function tableDraw(n){document.querySelectorAll('[data-mogedata]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===n)));$('moge-error').textContent=rows[n][0];$('moge-f1').textContent=rows[n][1];$('moge-label').textContent=rows[n][2];$('moge-desc').textContent=rows[n][3]}document.querySelectorAll('[data-mogedata]').forEach(b=>b.onclick=()=>tableDraw(+b.dataset.mogedata));tableDraw(0);
q([['Shape and scale','Why separate relative geometry from global scale?','The relative geometry branch can learn shape while a separate global scale head predicts scene size. This is a design choice to reduce interference during learning; the model can still estimate either part incorrectly.'],['Evidence and limitations','Improved labels raise boundary F1 in the reported ablation. Does this prove every filled-in pixel is correct?','No. It is an aggregate result under the paper’s evaluation protocol. The completion model can introduce errors, and the comparison does not validate individual pixels.'],['Single-view geometry','Does the point map establish the geometry behind an occluder?','No. It describes the visible image locations and can still be wrong. Hidden surfaces need other evidence or assumptions.']]);};

function render(){navigate();({play,data,detail,geometry})[state.section]()}
const initial=location.hash.slice(1);if(sections.some(([id])=>id===initial))state.section=initial;else if(initial==='targets'||initial==='scale')state.section='play';else if(initial==='architecture')state.section='data';window.addEventListener('hashchange',()=>{let id=location.hash.slice(1);if(sections.some(s=>s[0]===id)){state.section=id;render()}});render();
